{"success": true, "data": {"stdout": """"Aggregate eval results across seeds and compute summary statistics."""

import argparse
import json
import glob
import os
import sys

import numpy as np


def load_results_from_paths(paths: list[str]) -> list[dict]:
    results = []
    for p in paths:
        with open(p) as f:
            data = json.load(f)
        data["_path"] = p
        results.append(data)
    return results


def load_results_from_pattern(pattern: str) -> list[dict]:
    paths = sorted(glob.glob(pattern))
    return load_results_from_paths(paths)


def main():
    parser = argparse.ArgumentParser(
        description="Aggregate seed robustness results and compute mean±std."
    )
    parser.add_argument(
        "--pattern",
        default=None,
        help="Glob pattern for eval_results.json files",
    )
    parser.add_argument(
        "--paths", nargs="+", default=None,
        help="Explicit paths to eval_results.json files",
    )
    parser.add_argument(
        "--output", default=None,
        help="Output JSON path (default: print to stdout)",
    )
    args = parser.parse_args()

    if args.paths:
        results = load_results_from_paths(args.paths)
    elif args.pattern:
        results = load_results_from_pattern(args.pattern)
    else:
        results = load_results_from_pattern(
            "/root/autodl-tmp/trace-verdict-study-checkpoints/vota_seed*/final/eval_results.json"
        )

    if not results:
        print("No result files found.", file=sys.stderr)
        sys.exit(1)

    print(f"Found {len(results)} result files:")
    for r in results:
        print(f"  {r['_path']}")
    print()

    metrics_keys = ["accuracy", "pass_f1", "fail_f1"]
    seed_metrics = {}

    for r in results:
        path = r["_path"]
        seed_label = os.path.basename(os.path.dirname(os.path.dirname(path)))
        m = r["metrics"]
        row = {
            "accuracy": m["accuracy"],
            "pass_f1": m["pass_f1"],
            "fail_f1": m["fail_f1"],
        }
        seed_metrics[seed_label] = row
        print(f"{seed_label}: acc={m['accuracy']:.4f}  pass_f1={m['pass_f1']:.4f}  fail_f1={m['fail_f1']:.4f}")

    print()

    summary = {}
    for key in metrics_keys:
        values = [seed_metrics[s][key] for s in seed_metrics]
        summary[key] = {
            "mean": float(np.mean(values)),
            "std": float(np.std(values, ddof=1)) if len(values) > 1 else 0.0,
            "min": float(np.min(values)),
            "max": float(np.max(values)),
            "n_seeds": len(values),
        }
        print(f"{key}: {summary[key]['mean']:.4f} ± {summary[key]['std']:.4f} "
              f"(range: [{summary[key]['min']:.4f}, {summary[key]['max']:.4f}])")

    output_data = {
        "seeds": seed_metrics,
        "summary": summary,
        "n_seeds": len(results),
    }

    if args.output:
        os.makedirs(os.path.dirname(os.path.abspath(args.output)), exist_ok=True)
        with open(args.output, "w") as f:
            json.dump(output_data, f, indent=2)
        print(f"\nSaved to {args.output}")
    else:
        print("\n--- JSON output ---")
        print(json.dumps(output_data, indent=2))


if __name__ == "__main__":
    main()
